/// 🧪️ The neutral corpus drives the original source constructor and complete physical owner ladder.
#[cfg_attr(test,test)]
pub fn media_original_domain_pending_publication_and_cancelled_close(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for copy in [1,3,64]{
  let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:134217728,maximum_capacity_bytes:268435456,maximum_release_bytes:536870912,maximum_depth:4096};
  let((mut parent,mut source),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{
   let(cancel,_)=semio_framework_job::CancelToken::admit_root(stock).unwrap().unwrap();let(authority,_)=JobPayloadAuthority::admit(OperationId(corpus["sourceIdentity"][0].as_u64().unwrap()),Generation(corpus["sourceIdentity"][1].as_u64().unwrap()),stock).unwrap().unwrap();let(parent,_)=OriginalCallerSourceParent::admit(authority,cancel,stock).ok().unwrap();
   let row=&corpus["cases"][0]["source"];(parent,Some(MediaOperationRefusal{source:MediaOperationSource::Media(MediaError::Payload(row["port"].as_str().unwrap().into(),row["message"].as_str().unwrap().into()))}))
  });
  let(mut born,mut released)=(heap.requested_bytes,heap.released_bytes);let pointers=match &source.as_ref().unwrap().source{MediaOperationSource::Media(MediaError::Payload(port,message))=>(port.as_ptr(),message.as_ptr()),_=>unreachable!()};
  let mut sequence=0;let mut recipient=Default::default();let mut cx=parent.borrow_context(StepBudget::new(32768,1500,stock),||Some(1000),&mut sequence,&mut recipient).unwrap();let identity=cx.original_recipient_identity();let mut failure=None;
  for row in corpus["cases"].as_array().unwrap(){
   let loan=RetainedCloneGrant{maximum_capacity_bytes:row["capacity"].as_u64().unwrap()as usize,..stock};let before=cx.retained_progress();let fuel=cx.fuel_remaining();
   let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|{failure=admit_original_domain_failure(&mut source,same)?;Ok(failure.is_some())}));
   assert_eq!(result.unwrap(),row["expected"]=="published");if failure.is_some(){assert!(source.is_none());assert_eq!(heap.requested_bytes,original_domain_failure_demand::<MediaOperationRefusal>().capacity_bytes);assert_eq!(heap.released_bytes,0);assert_eq!(cx.fuel_remaining(),fuel-1)}else{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);match &source.as_ref().unwrap().source{MediaOperationSource::Media(MediaError::Payload(port,message))=>assert_eq!((port.as_ptr(),message.as_ptr()),pointers),_=>unreachable!()}}
   born+=heap.requested_bytes;released+=heap.released_bytes;assert_eq!(cx.original_recipient_identity(),identity);
  }
  let failure=failure.unwrap();let domain=failure.primary_domain().unwrap();let projection=domain.projection();assert_eq!(domain.message().as_ptr(),pointers.1);assert!(matches!(projection.projection_view(&[1]).unwrap(),V::IntrinsicText(port)if port.as_ptr()==pointers.0));assert!(matches!(projection.projection_view(&[2]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointers.1));assert!(matches!(projection.projection_view(&[3]).unwrap(),V::IntrinsicNull));assert!(matches!(projection.projection_view(&[4]).unwrap(),V::IntrinsicNull));assert_eq!(projection.projection_key(&[],4).unwrap(),"accepted");
  let(mut closing,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("media original domain supports controlled retirement")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));parent.cancellation().unwrap().cancel_now();
  for turn in 0..32768{if closing.terminal_is_empty(){break}let before=cx.retained_progress();let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..stock};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|close_original_retained_step(same,closing.selected_demand(copy)?,|grant|closing.step(grant)).map(|step|step.progress())));let effects=result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));assert_eq!(cx.retained_progress(),before.checked_add(effects).unwrap());born+=heap.requested_bytes;released+=heap.released_bytes;assert!(turn<32767);assert!(cx.is_cancelled());assert_eq!(cx.original_recipient_identity(),identity)}
  assert!(closing.terminal_is_empty());drop(cx);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for turn in 0..128{if parent.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parent.close_step(stock));let effects=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(effects.retained_capacity_bytes,effects.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;assert!(turn<127)}assert!(parent.terminal_is_empty());assert_eq!(born,released);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(parent));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
}

